(self.webpackChunkvuepress_blog=self.webpackChunkvuepress_blog||[]).push([[2485],{950:(e,l,a)=>{"use strict";a.r(l),a.d(l,{data:()=>i});const i={key:"v-59ee54ab",path:"/pages/ai-energize/",title:"",lang:"zh-CN",frontmatter:{home:!1,sidebar:!1},excerpt:"",headers:[{level:3,title:"技术文档列表",slug:"技术文档列表",children:[]},{level:3,title:"实用资源",slug:"实用资源",children:[]},{level:3,title:"概念理解",slug:"概念理解",children:[]}],filePathRelative:"pages/ai-energize/README.md",git:{updatedTime:1776756909e3,contributors:[{name:"COOKIES-LGL",email:"1344714332@qq.com",commits:3}]}}},4536:(e,l,a)=>{"use strict";a.r(l),a.d(l,{default:()=>t});const i=(0,a(6252).uE)('<h3 id="技术文档列表"><a class="header-anchor" href="#技术文档列表">#</a> 技术文档列表</h3><ul><li><a href="./dev-energize">开发赋能</a> <span style="color:#bbb;float:right;">2025-12-30</span></li><li><a href="./skills">Skills</a> <span style="color:#bbb;float:right;">2026-01-10</span></li><li><a href="./code-review">CodeReview</a> <span style="color:#bbb;float:right;">2026-02-10</span></li><li><a href="./agent">Agent</a> <span style="color:#bbb;float:right;">2025-11-10</span></li><li><a href="./mcp">MCP</a> <span style="color:#bbb;float:right;">2025-12-10</span></li></ul><h3 id="实用资源"><a class="header-anchor" href="#实用资源">#</a> 实用资源</h3><h3 id="概念理解"><a class="header-anchor" href="#概念理解">#</a> 概念理解</h3><ul><li><p>MCP 给了智能体连接外部世界的“手”，而 Skills 则赋予了它高效完成专业任务的“肌肉记忆”或“经验。</p></li><li><p>对于 Agent 日常的工具调用——查文件、跑命令、读数据——MCP 引入了不必要的复杂性和成本， CLI 更好用，CLI 是 LLM 的母语。但对于远程服务连接，MCP 有它的价值。MCP 不该被丢掉，但也不该占着”通用工具协议”的位置不放。</p></li><li><p>MCP 解决的核心问题是连接（connecting），而 CLI 和 Agent Skills 解决的是使用（using）。</p></li></ul>',5),t={render:function(e,l){return i}}}}]);